            <h1>{MICRO_COPY['chat.header.title']}</h1>
          </header>
          <div className="chat-history">
            <AnimatePresence initial={false}>
              {messages.map(msg => <ChatMessage key={msg.id} msg={msg} />)}
            </AnimatePresence>
            {isChatLoading && (
              <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="message ai-message">
                <lucide.Loader2 className="spinner" size={16} /> Thinking...
              </motion.div>
            )}
            <div ref={chatEndRef} />
          </div>
          {currentScreen === 'screen_01_concierge_intro' && messages.length === 1 && (
            <div className="chat-suggestions">
              <button className="chip" onClick={() => handleSendChat("Find me frontend roles in NYC")}>Find me frontend roles in NYC</button>
              <button className="chip" onClick={() => handleSendChat("Roles that use my Wayfair QA experience")}>Roles that use my Wayfair QA experience</button>
            </div>
          )}
          <div className="chat-input-area">
            <div className={`input-wrapper ${chatError ? 'error' : ''}`}>
              <input 
                type="text" 
                placeholder={MICRO_COPY['chat.input.placeholder']}
                value={chatInput}
                onChange={e => setChatInput(e.target.value)}
                onKeyDown={e => e.key === 'Enter' && handleSendChat()}
                disabled={isChatLoading}
              />
              <button className="send-btn" onClick={() => handleSendChat()} disabled={!chatInput.trim() || isChatLoading} aria-label="Send">
                <lucide.Send size={18} />
              </button>
            </div>
          </div>
        </article>
      )}
    </aside>
  );

  const renderRightPane = () => {
    switch (currentScreen) {
      case 'screen_01_concierge_intro':
        return (
          <section className="right-pane">
            <article className="p-aspot aspot-coop">
              <motion.div className="hero-content" initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.5 }}>
