                        </div>
                      </div>
                      <div className="card-footer">
                        <button className="btn-secondary" style={{ width: '100%' }}>{MICRO_COPY['rec.card.button.view']}</button>
                      </div>
                    </motion.div>
                  ))
                )}
              </div>
            </article>
          </section>
        );

      case 'screen_03_employer_detail_gap':
        if (!selectedEmployer) return null;
        return (
