                    </div>
                    <div className="gaps panel">
                      <h3><lucide.AlertTriangle size={18} /> {MICRO_COPY['eval.panel.gaps']}</h3>
                      <ul>
                        {gapAnalysisData.critical_gaps?.map((g, i) => <li key={i}>{g}</li>)}
                      </ul>
                    </div>
                  </div>

                  <article className="p-counterfactual">
                    <motion.div className="reveal-box" initial={{ backgroundColor: 'var(--surface)' }} whileInView={{ backgroundColor: '#FAEDED' }} transition={{ duration: 1 }}>
