                            const emp = SEED_EMPLOYERS.find(e => e.id === app.employer_id) || SEED_EMPLOYERS[0];
                            return (
                              <div key={app.id} className="kanban-card" draggable onDragStart={(e) => onDragStart(e, app.id)}>
