                                <span className="role">{emp.role_title}</span>
                                <div className="progress-bar"><div className="fill" style={{ width: `${app.probability_score}%` }}></div></div>
                                <span className="next-action">Action: {app.next_action}</span>
                              </div>
                            );
                          })}
                        </div>
                      </div>
                    );
                  })}
                </div>
              </article>
            </motion.div>

            {showHitlModal && (
              <div className="modal-overlay" role="dialog" aria-modal="true">
                <article className="p-hitl" tabIndex="-1" ref={el => el && el.focus()} style={{ outline: 'none' }}>
                  <h3><lucide.AlertTriangle size={20} /> {MICRO_COPY['hitl.modal.title']}</h3>
                  <p>{MICRO_COPY['hitl.modal.body']}</p>
                  <div className="modal-actions">
                    <button className="btn-secondary" onClick={() => { setShowHitlModal(false); setPendingDrop(null); }}>{MICRO_COPY['hitl.button.cancel']}</button>
                    <button className="btn-primary" onClick={confirmDrop}>{MICRO_COPY['hitl.button.confirm']}</button>
                  </div>
                </article>
              </div>
            )}
          </section>
        );

      default: return null;
    }
  };

  return (
    <div style={{ position: 'relative' }}>
      <GlobalStyles />
      <main className={currentScreen === 'screen_05_tracking_board' ? 'nu-layout-full' : 'nu-layout-split'}>
        {renderSidebarChat()}
        {renderRightPane()}
      </main>

      {/* Toasts */}
      <div className="toast-container">
        <AnimatePresence>
          {toasts.map(t => (
            <motion.div key={t.id} className="toast" initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, scale: 0.9 }}>
              <lucide.CheckCircle2 size={16} color="var(--ok)" /> {t.msg}
            </motion.div>
          ))}
        </AnimatePresence>
      </div>

      {/* Demo Controls */}
      <div style={{ position: 'fixed', bottom: 16, right: 16, zIndex: 9999, background: 'var(--rail)', padding: '8px 12px', borderRadius: 8, display: 'flex', gap: 12, alignItems: 'center', boxShadow: 'var(--shadow-md)' }}>
        <span style={{ color: 'var(--muted)', fontSize: 11, textTransform: 'uppercase', fontWeight: 700 }}>Demo Jump</span>
        <select 
          value={currentScreen} 
          onChange={(e) => setCurrentScreen(e.target.value)} 
          style={{ color: 'var(--on-accent)', background: 'transparent', border: '1px solid var(--muted)', padding: '4px 8px', borderRadius: 4, fontSize: 13, outline: 'none' }}
        >
          <option value="screen_01_concierge_intro">01: Intro</option>
          <option value="screen_02_lookbook_curation">02: Lookbook</option>
          <option value="screen_03_employer_detail_gap">03: Detail</option>
          <option value="screen_04_gap_analysis_results">04: Gap Analysis</option>
          <option value="screen_05_tracking_board">05: Tracker</option>
        </select>
      </div>
    </div>
  );
};

function __test_state_transitions__() {
  console.assert(typeof App === 'function', 'App must be a component');
  return true;
}
if (typeof window !== 'undefined') {
  window.__hicProtoTests = __test_state_transitions__;
}

