    .panel ul { padding-left: 20px; font-size: 15px; line-height: 1.6; margin-top: 16px; }
    .strengths h3 { color: var(--ok); }
    .gaps h3 { color: var(--warn); }

    .p-counterfactual { margin-bottom: 48px; }
    .reveal-box { background: var(--surface); border: 1px solid var(--border); border-left: 4px solid var(--accent); border-radius: var(--radius-md); padding: 32px; transition: background 0.5s; }
    .shift-statement { font-size: 20px; line-height: 1.5; margin-bottom: 32px; }
    .shift-statement strong { color: var(--accent); font-size: 24px; }
    .pull-row { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; border-top: 1px solid var(--border); padding-top: 24px; }
    .pull-row .stat strong { font-family: var(--mono); font-weight: 700; }

    .p-rubric { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-md); padding: 32px; margin-bottom: 32px; }
    .action-steps { padding-left: 24px; font-size: 16px; line-height: 1.6; }
    .action-steps li { margin-bottom: 16px; padding-left: 8px; }
    .action-steps li::marker { font-weight: 700; color: var(--accent); }

    /* p-portfolio-mix (Kanban) */
    .kanban-board { display: flex; gap: 24px; overflow-x: auto; padding-bottom: 24px; height: calc(100vh - 200px); }
    .column { flex: 0 0 320px; background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-md); display: flex; flex-direction: column; }
    .column h3 { padding: 16px; margin: 0; border-bottom: 1px solid var(--border); font-size: 14px; text-transform: uppercase; letter-spacing: 0.05em; color: var(--muted); background: var(--panel); border-top-left-radius: var(--radius-md); border-top-right-radius: var(--radius-md); }
    .column-body { padding: 16px; flex-grow: 1; overflow-y: auto; display: flex; flex-direction: column; gap: 12px; }
    .column-body.drag-over { background: rgba(200,16,46,0.05); border: 2px dashed var(--accent); border-radius: var(--radius-md); }
    .kanban-card { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-sm); padding: 16px; box-shadow: var(--shadow-sm); cursor: grab; }
    .kanban-card:active { cursor: grabbing; }
    .kanban-card h4 { margin: 0 0 4px 0; font-size: 16px; }
    .kanban-card .role { font-size: 13px; color: var(--muted); display: block; margin-bottom: 12px; }
    .progress-bar { height: 6px; background: var(--panel); border-radius: var(--radius-pill); overflow: hidden; margin-bottom: 8px; }
    .progress-bar .fill { height: 100%; background: var(--ok); }
    .next-action { font-size: 12px; color: var(--text); display: block; }

    /* p-forecast-band */
    .p-forecast-band { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-md); padding: 16px 24px; display: inline-flex; align-items: center; gap: 24px; margin-bottom: 32px; }
    .forecast-readout { display: flex; align-items: center; gap: 12px; }
    .forecast-readout span { font-size: 14px; color: var(--muted); }
    .forecast-readout strong { font-size: 16px; color: var(--text); }
    .band-visual { display: flex; align-items: center; gap: 4px; height: 24px; background: var(--panel); border-radius: var(--radius-pill); padding: 0 12px; position: relative; width: 200px; }
    .band-visual::before { content: ''; position: absolute; left: 10%; right: 10%; height: 4px; background: rgba(29,110,100,0.2); top: 10px; border-radius: 2px; }
    .band-visual .p50 { position: absolute; left: 50%; transform: translateX(-50%); background: var(--ok); color: var(--on-accent); font-size: 10px; font-weight: 700; padding: 2px 6px; border-radius: 4px; z-index: 2; }
    .band-visual .p10, .band-visual .p90 { position: absolute; font-size: 10px; color: var(--muted); top: 28px; }
    .band-visual .p10 { left: 0; }
    .band-visual .p90 { right: 0; }

    /* p-hitl Modal */
    .modal-overlay { position: fixed; inset: 0; background: rgba(11,19,38,0.6); display: flex; align-items: center; justify-content: center; z-index: 1000; }
    .p-hitl { background: var(--surface); border-radius: var(--radius-md); padding: 32px; max-width: 400px; width: 100%; box-shadow: 0 24px 48px rgba(0,0,0,0.2); outline: none; }
    .p-hitl h3 { margin-bottom: 16px; color: var(--accent); display: flex; align-items: center; gap: 8px; }
    .p-hitl p { margin-bottom: 32px; font-size: 15px; }
    .modal-actions { display: flex; justify-content: flex-end; gap: 16px; }

    /* Animations & Loaders */
    @keyframes shake { 0%, 100% { transform: translateX(0); } 25% { transform: translateX(-4px); } 75% { transform: translateX(4px); } }
    @keyframes shimmer { 0% { background-position: -200% 0; } 100% { background-position: 200% 0; } }
    @keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.5; } }
    @keyframes scan { 0% { top: 0; opacity: 0; } 10% { opacity: 1; } 90% { opacity: 1; } 100% { top: 100%; opacity: 0; } }

    .skeleton { background: linear-gradient(90deg, var(--panel) 25%, var(--border) 50%, var(--panel) 75%); background-size: 200% 100%; animation: shimmer 1.5s infinite; border-radius: var(--radius-sm); }
    .skeleton-text { height: 16px; margin-bottom: 8px; width: 100%; }
    .skeleton-text.short { width: 60%; }
    .skeleton-title { height: 24px; width: 40%; margin-bottom: 16px; }

    .p-synth { position: relative; overflow: hidden; }
    .p-synth::after { content: ''; position: absolute; left: 0; right: 0; height: 2px; background: var(--accent); box-shadow: 0 0 8px var(--accent); animation: scan 2s ease-in-out infinite; z-index: 10; }

    .spinner { animation: spin 1s linear infinite; }
    @keyframes spin { 100% { transform: rotate(360deg); } }

    /* Toast */
    .toast-container { position: fixed; bottom: 24px; left: 50%; transform: translateX(-50%); z-index: 9999; display: flex; flex-direction: column; gap: 8px; }
    .toast { background: var(--rail); color: var(--on-accent); padding: 12px 24px; border-radius: var(--radius-pill); font-size: 14px; font-weight: 700; display: flex; align-items: center; gap: 8px; box-shadow: var(--shadow-md); }

    @media (max-width: 768px) {
      .nu-layout-split { flex-direction: column; }
      .left-pane { width: 100%; height: 50vh; border-right: none; border-bottom: 1px solid var(--border); }
      .right-pane { height: 50vh; }
      .content-grid, .eval-grid, .pull-row { grid-template-columns: 1fr; }
      .p-aspot { padding: 32px; }
    }
    @media (prefers-reduced-motion: reduce) {
      * { animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; transition-duration: 0.01ms !important; scroll-behavior: auto !important; }
    }
  `}</style>
);

// --- COMPONENTS ---

const ChatMessage = ({ msg }) => {
  const isAI = msg.sender === 'ai';
  return (
    <motion.div 
      initial={{ opacity: 0, y: 12 }} 
      animate={{ opacity: 1, y: 0 }} 
      transition={{ duration: 0.3, ease: "easeOut" }}
      className={`message ${isAI ? 'ai-message' : 'user-message'}`}
    >
      {msg.isTrail && (
        <article className="p-trail">
          <details>
            <summary><lucide.Sparkles size={14} /> Reasoning Trail</summary>
            <ul>
              <li>Parsed intent: Frontend, NYC, React (current), Next.js (desired)</li>
              <li>Filtered 4,200 NUworks records &rarr; 14 matches</li>
              <li>Ranked by CS '25 cohort success rate</li>
            </ul>
          </details>
        </article>
      )}
      {msg.text}
      {msg.action && <div style={{ marginTop: 16 }}>{msg.action}</div>}
    </motion.div>
  );
};

const SkeletonCard = () => (
  <div className="employer-card" style={{ pointerEvents: 'none' }}>
    <div className="card-header">
      <div className="skeleton skeleton-title"></div>
      <div className="skeleton" style={{ width: 40, height: 20, borderRadius: 999 }}></div>
    </div>
    <div className="card-body">
      <div className="skeleton skeleton-text"></div>
      <div className="skeleton skeleton-text"></div>
      <div className="skeleton skeleton-text short"></div>
    </div>
    <div className="card-footer" style={{ marginTop: 24 }}>
      <div className="skeleton" style={{ width: 100, height: 36, borderRadius: 4 }}></div>
    </div>
  </div>
);

// --- MAIN APP ---
const App = () => {
  const [currentScreen, setCurrentScreen] = useState('screen_01_concierge_intro');
  const [messages, setMessages] = useSessionState('nu_messages', INITIAL_MESSAGES);
  const [chatInput, setChatInput] = useState('');
  const [isChatLoading, setIsChatLoading] = useState(false);
  const [chatError, setChatError] = useState(false);

  const [curatedEmployers, setCuratedEmployers] = useState([]);
  const [isGeneratingMatches, setIsGeneratingMatches] = useState(false);

  const [selectedEmployer, setSelectedEmployer] = useState(null);

  const [gapAnalysisData, setGapAnalysisData] = useSessionState('nu_gap_data', null);
  const [isAnalyzingGap, setIsAnalyzingGap] = useState(false);

  const [trackedApplications, setTrackedApplications] = useSessionState('nu_tracked_apps', SEED_TRACKED);
  const [showHitlModal, setShowHitlModal] = useState(false);
  const [pendingDrop, setPendingDrop] = useState(null);

  const [avatarUrl, setAvatarUrl] = useState(null);
  const [toasts, setToasts] = useState([]);

  const chatEndRef = useRef(null);

  // Scroll chat to bottom
  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  // Load Avatar
  useEffect(() => {
    generateImage(PERSONA.avatarPrompt).then(url => {
      if (url) setAvatarUrl(url);
    });
  }, []);

  const addToast = (msg) => {
    const id = Date.now();
    setToasts(prev => [...prev, { id, msg }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 3000);
  };

  // --- ACTIONS ---

  const handleSendChat = async (overrideText = null) => {
    const text = overrideText || chatInput;
    if (!text.trim()) return;

    const newUserMsg = { id: Date.now(), sender: 'user', text, timestamp: new Date().toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}) };
    setMessages(prev => [...prev, newUserMsg]);
    setChatInput('');
    setChatError(false);

    // Trigger logic based on current screen
    if (currentScreen === 'screen_01_concierge_intro') {
      setIsGeneratingMatches(true);
      setIsChatLoading(true);
      setCurrentScreen('screen_02_lookbook_curation');

      try {
        const sysPrompt = `You are an expert Northeastern University Co-op advisor. Given a student's profile, past experience, and natural language preferences, query the employer database and return the top 3 matches. For each match, write a custom 2-sentence 'why_this_fits' blurb that directly connects their prompt to the job.`;
        const userPrompt = `User Prompt: ${text}. Student Profile: Major: ${PERSONA.major}, Past Co-op: ${PERSONA.priorCoop}. Known Skills: ${PERSONA.knownSkills.join(', ')}.`;

        const data = await callAIForJSON(sysPrompt, userPrompt, { 
          array: true, 
          useVS: true,
          fallback: SEED_EMPLOYERS.slice(0,3).map(e => ({ employer_id: e.id, why_this_fits: "Fallback match based on your profile.", match_score: e.match_score, difficulty_tier: e.difficulty_tier }))
        });

        // Map AI response to full employer data
        const enriched = (data || []).map(aiMatch => {
          const base = SEED_EMPLOYERS.find(e => e.id === aiMatch.employer_id) || SEED_EMPLOYERS[0];
          return { ...base, why_this_fits: aiMatch.why_this_fits, match_score: aiMatch.match_score || base.match_score, difficulty_tier: aiMatch.difficulty_tier || base.difficulty_tier };
        });

        setCuratedEmployers(enriched);
        setMessages(prev => [...prev, { 
          id: Date.now()+1, 
          sender: 'ai', 
          text: "Here are the top 3 matches I found that fit your criteria.", 
          isTrail: true,
          timestamp: new Date().toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}) 
        }]);
      } catch (err) {
        setChatError(true);
        addToast("Failed to connect to matching engine.");
        setCurrentScreen('screen_01_concierge_intro'); // Revert
      } finally {
        setIsGeneratingMatches(false);
        setIsChatLoading(false);
      }
    } else {
      // Generic chat response for other screens
      setIsChatLoading(true);
      setTimeout(() => {
        setMessages(prev => [...prev, { id: Date.now()+1, sender: 'ai', text: "I've noted that preference. Let's focus on the current step.", timestamp: new Date().toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}) }]);
        setIsChatLoading(false);
      }, 1000);
    }
  };

  const handleViewDetails = (employer) => {
    setSelectedEmployer(employer);
    setCurrentScreen('screen_03_employer_detail_gap');
    setTimeout(() => {
      setMessages(prev => [...prev, { 
        id: Date.now(), 
        sender: 'ai', 
        text: `${employer.company_name} is highly competitive, but not impossible. Want me to run a gap analysis to see exactly what you'd need to learn?`,
        action: <button className="btn-primary" onClick={handleAnalyzeGap} disabled={isAnalyzingGap}><lucide.Sparkles size={16}/> {isAnalyzingGap ? 'Analyzing...' : 'Yes, analyze the gap'}</button>,
        timestamp: new Date().toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}) 
      }]);
    }, 500);
  };

  const handleAnalyzeGap = async () => {
    setIsAnalyzingGap(true);
    setCurrentScreen('screen_04_gap_analysis_results');

    try {
      const sysPrompt = `You are a technical career coach at Northeastern University. Compare the student's resume/skills against the specific job description. Extract 2 matched strengths, 2 critical gaps, and generate a highly specific, actionable 3-step plan to bridge the gap before an interview.`;
      const userPrompt = `Student Skills: ${PERSONA.knownSkills.join(', ')}. Job Description: ${selectedEmployer.job_description}.`;

      const data = await callAIForJSON(sysPrompt, userPrompt, {
        useVS: true,
        fallback: {
          matched_strengths: ["React fundamentals", "Agile experience"],
          critical_gaps: ["Server-side rendering", "Next.js App Router"],
          action_plan: [
            { step_title: "Complete LinkedIn Learning", description: "Next.js Essential Training (4 hrs)" },
            { step_title: "Build Mini-Project", description: "Convert your Wayfair QA dashboard mockup into a Next.js SSR app." },
            { step_title: "Resume Update", description: "Add the mini-project to your 'Projects' section highlighting SSR." }
          ]
        }
      });

      setGapAnalysisData(data);
      setMessages(prev => [...prev, { 
        id: Date.now(), 
        sender: 'ai', 
        text: `Here is your custom action plan for the ${selectedEmployer.company_name} role.`,
        timestamp: new Date().toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}) 
      }]);
    } catch (err) {
      addToast("Analysis failed. Please try again.");
      setCurrentScreen('screen_03_employer_detail_gap');
    } finally {
      setIsAnalyzingGap(false);
    }
  };

  const handleAddToTracker = () => {
    const newApp = {
      id: `trk_new_${Date.now()}`,
      employer_id: selectedEmployer.id,
      status: "Saved/Upskilling",
      probability_score: 64,
      next_action: gapAnalysisData?.action_plan?.[0]?.step_title || "Review action plan"
    };
    setTrackedApplications(prev => [newApp, ...prev]);
    setCurrentScreen('screen_05_tracking_board');
    addToast("Added to Tracker");
  };

  // Drag and Drop Handlers for Kanban
  const onDragStart = (e, appId) => { e.dataTransfer.setData("appId", appId); };
  const onDragOver = (e) => { e.preventDefault(); e.currentTarget.classList.add('drag-over'); };
  const onDragLeave = (e) => { e.currentTarget.classList.remove('drag-over'); };
  const onDrop = (e, status) => {
    e.preventDefault();
    e.currentTarget.classList.remove('drag-over');
    const appId = e.dataTransfer.getData("appId");

    if (status === 'Applied') {
      setPendingDrop({ appId, status });
      setShowHitlModal(true);
    } else {
      updateAppStatus(appId, status);
    }
  };

  const updateAppStatus = (appId, status) => {
    setTrackedApplications(prev => prev.map(app => app.id === appId ? { ...app, status } : app));
  };

  const confirmDrop = () => {
    if (pendingDrop) {
      updateAppStatus(pendingDrop.appId, pendingDrop.status);
      addToast("Official NUworks drop triggered.");
    }
    setShowHitlModal(false);
    setPendingDrop(null);
  };

  // --- RENDERERS ---

  const renderSidebarChat = () => (
    <aside className={currentScreen === 'screen_05_tracking_board' ? 'sidebar-collapsed' : 'left-pane'}>
      {currentScreen === 'screen_05_tracking_board' ? (
        <button className="icon-btn" onClick={() => setCurrentScreen('screen_01_concierge_intro')} aria-label="Expand Chat" style={{ padding: 12, borderRadius: 8, background: 'var(--panel)' }}>
          <lucide.MessageSquare size={24} color="var(--text)" />
        </button>
      ) : (
        <article className="p-chat">
          <header className="chat-header">
            {avatarUrl ? <img src={avatarUrl} className="avatar" alt="Alex" /> : <div className="avatar" />}
            <h1>{MICRO_COPY['chat.header.title']}</h1>
          </header>
          <div className="chat-history">
            <AnimatePresence initial={false}>
              {messages.map(msg => <ChatMessage key={msg.id} msg={msg} />)}
            </AnimatePresence>
            {isChatLoading && (
              <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="message ai-message">
                <lucide.Loader2 className="spinner" size={16} /> Thinking...
              </motion.div>
            )}
            <div ref={chatEndRef} />
          </div>
          {currentScreen === 'screen_01_concierge_intro' && messages.length === 1 && (
            <div className="chat-suggestions">
              <button className="chip" onClick={() => handleSendChat("Find me frontend roles in NYC")}>Find me frontend roles in NYC</button>
              <button className="chip" onClick={() => handleSendChat("Roles that use my Wayfair QA experience")}>Roles that use my Wayfair QA experience</button>
            </div>
          )}
          <div className="chat-input-area">
            <div className={`input-wrapper ${chatError ? 'error' : ''}`}>
              <input 
                type="text" 
                placeholder={MICRO_COPY['chat.input.placeholder']}
                value={chatInput}
                onChange={e => setChatInput(e.target.value)}
                onKeyDown={e => e.key === 'Enter' && handleSendChat()}
                disabled={isChatLoading}
              />
              <button className="send-btn" onClick={() => handleSendChat()} disabled={!chatInput.trim() || isChatLoading} aria-label="Send">
                <lucide.Send size={18} />
              </button>
            </div>
          </div>
        </article>
      )}
    </aside>
  );

  const renderRightPane = () => {
    switch (currentScreen) {
      case 'screen_01_concierge_intro':
        return (
          <section className="right-pane">
            <article className="p-aspot aspot-coop">
              <motion.div className="hero-content" initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.5 }}>
                <h2>{MICRO_COPY['aspot.hero.title']}</h2>
                <p>{MICRO_COPY['aspot.hero.subtitle']}</p>
                <div className="stats-row">
                  <div className="stat"><span>{MICRO_COPY['aspot.stat.major.label']}</span><strong>{MICRO_COPY['aspot.stat.major.value']}</strong></div>
                  <div className="stat"><span>{MICRO_COPY['aspot.stat.coop.label']}</span><strong>{MICRO_COPY['aspot.stat.coop.value']}</strong></div>
                </div>
              </motion.div>
            </article>
          </section>
        );

      case 'screen_02_lookbook_curation':
        return (
          <section className="right-pane">
            <article className="p-rec">
              <header className="rec-header">
                <h2>{MICRO_COPY['rec.header.title']}</h2>
              </header>
              <div className="rec-grid">
                {isGeneratingMatches ? (
                  <>
                    <SkeletonCard /><SkeletonCard /><SkeletonCard />
                  </>
                ) : (
                  curatedEmployers.map((emp, idx) => (
                    <motion.div 
                      key={emp.id}
                      className="employer-card"
                      initial={{ opacity: 0, scale: 0.95, y: 20 }}
                      animate={{ opacity: 1, scale: 1, y: 0 }}
                      transition={{ duration: 0.4, delay: idx * 0.1 }}
                      onClick={() => handleViewDetails(emp)}
                    >
                      <div className="card-header">
                        <h3>{emp.company_name}</h3>
                        <span className={`badge ${emp.difficulty_tier.toLowerCase()}`}>{emp.difficulty_tier}</span>
                        <span className="match-score">{emp.match_score} Fit</span>
                      </div>
                      <div className="card-body">
                        <p className="ai-blurb">{emp.why_this_fits}</p>
                        <div className="card-stats">
                          <span>{emp.w23_placements} W23 Placements</span>
                          <span>${emp.hourly_rate}/hr Median</span>
                        </div>
                      </div>
                      <div className="card-footer">
                        <button className="btn-secondary" style={{ width: '100%' }}>{MICRO_COPY['rec.card.button.view']}</button>
                      </div>
                    </motion.div>
                  ))
                )}
              </div>
            </article>
          </section>
        );

      case 'screen_03_employer_detail_gap':
        if (!selectedEmployer) return null;
        return (
          <section className="right-pane">
            <motion.article className="p-info-flow" initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} transition={{ duration: 0.4 }}>
              <header className="employer-header">
                <h2>{selectedEmployer.company_name} - {selectedEmployer.role_title}</h2>
                <div className="meta-tags">
                  <span>{selectedEmployer.location}</span>
                  <span className={`badge ${selectedEmployer.difficulty_tier.toLowerCase()}`}>{selectedEmployer.difficulty_tier}</span>
                  <span>${selectedEmployer.hourly_rate}/hr</span>
                </div>
              </header>
              <div className="content-grid">
                <div className="job-description">
                  <h3>Role Overview</h3>
                  <p>{selectedEmployer.job_description}</p>
                  <div style={{ marginTop: 24 }}>
                    <span className="meta">Tech Stack</span>
                    <div style={{ display: 'flex', gap: 8, marginTop: 8 }}>
                      {selectedEmployer.tech_stack.map(t => <span key={t} className="chip">{t}</span>)}
                    </div>
                  </div>
                </div>
                <aside className="university-requirements">
                  <h3>{MICRO_COPY['info.header.requirements']}</h3>
                  <ul>
                    <li>Must have completed CS3500</li>
                    <li>Minimum 3.0 GPA required for Reach tier</li>
                  </ul>
                </aside>
              </div>
              <article className="p-vignette-trio">
                <h3>{MICRO_COPY['info.vignette.title']}</h3>
                <div className="vignette-cards">
                  {SEED_PEERS.slice(0,3).map(peer => (
                    <div key={peer.id} className="vignette">
                      <strong>{peer.cohort_code}</strong>
                      Bridged: {peer.gap_bridged}<br/>
                      Placed: {peer.final_placement} (${peer.hourly_rate}/hr)
                    </div>
                  ))}
                </div>
              </article>
            </motion.article>
          </section>
        );

      case 'screen_04_gap_analysis_results':
        return (
          <section className="right-pane">
            <article className={`p-eval ${isAnalyzingGap ? 'p-synth' : ''}`}>
              <header style={{ marginBottom: 32 }}>
                <h2>{MICRO_COPY['eval.header.title']}</h2>
              </header>

              {isAnalyzingGap ? (
                <div style={{ padding: 48, textAlign: 'center', color: 'var(--muted)' }}>
                  <lucide.Loader2 className="spinner" size={32} style={{ marginBottom: 16, color: 'var(--accent)' }} />
                  <p>Analyzing resume against job description...</p>
                </div>
              ) : gapAnalysisData ? (
                <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 0.5 }}>
                  <div className="eval-grid">
                    <div className="strengths panel">
                      <h3><lucide.CheckCircle2 size={18} /> {MICRO_COPY['eval.panel.strengths']}</h3>
                      <ul>
                        {gapAnalysisData.matched_strengths?.map((s, i) => <li key={i}>{s}</li>)}
                      </ul>
                    </div>
                    <div className="gaps panel">
                      <h3><lucide.AlertTriangle size={18} /> {MICRO_COPY['eval.panel.gaps']}</h3>
                      <ul>
                        {gapAnalysisData.critical_gaps?.map((g, i) => <li key={i}>{g}</li>)}
                      </ul>
                    </div>
                  </div>

                  <article className="p-counterfactual">
                    <motion.div className="reveal-box" initial={{ backgroundColor: 'var(--surface)' }} whileInView={{ backgroundColor: '#FAEDED' }} transition={{ duration: 1 }}>
                      <h3>{MICRO_COPY['counterfactual.box.title']}</h3>
                      <p className="shift-statement">
                        If you apply today, you have an <strong>11%</strong> probability of securing an interview. If you complete the 3-step bridge plan below, historical cohort data suggests your probability shifts to <strong>64%</strong>.
                      </p>
                      <div className="pull-row">
                        <div className="stat"><span>{MICRO_COPY['counterfactual.stat.current']}</span><strong>11%</strong></div>
                        <div className="stat"><span>{MICRO_COPY['counterfactual.stat.bridged']}</span><strong>64%</strong></div>
                        <div className="stat"><span>{MICRO_COPY['counterfactual.stat.offer']}</span><strong>${selectedEmployer?.hourly_rate || 52}/hr</strong></div>
                        <div className="stat"><span>{MICRO_COPY['counterfactual.stat.peers']}</span><strong>14</strong></div>
                      </div>
                    </motion.div>
                  </article>

                  <article className="p-rubric">
                    <h3><lucide.Map size={18} style={{ display: 'inline', verticalAlign: 'text-bottom', marginRight: 8 }}/> {MICRO_COPY['rubric.header.title']}</h3>
                    <ol className="action-steps">
                      {gapAnalysisData.action_plan?.map((step, i) => (
                        <li key={i}><strong>{step.step_title}:</strong> {step.description}</li>
                      ))}
                    </ol>
                  </article>

                  <div style={{ display: 'flex', justifyContent: 'flex-end' }}>
                    <button className="btn-primary" onClick={handleAddToTracker}>
                      <lucide.Plus size={16} /> {MICRO_COPY['rubric.button.add']}
                    </button>
                  </div>
                </motion.div>
              ) : null}
            </article>
          </section>
        );

      case 'screen_05_tracking_board':
        const cols = ["Saved/Upskilling", "Ready to Apply", "Applied", "Interviewing", "Offer"];
        return (
          <section className="main-content">
            <motion.div initial={{ opacity: 0, scale: 0.98 }} animate={{ opacity: 1, scale: 1 }} transition={{ duration: 0.4 }}>
              <header style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end', marginBottom: 32 }}>
                <h2>{MICRO_COPY['board.header.title']}</h2>
                <article className="p-forecast-band">
                  <div className="forecast-readout">
                    <span>{MICRO_COPY['board.forecast.label']}</span>
                    <strong>Oct 14 - Oct 28</strong>
                    <div className="band-visual">
                      <div className="p10">Oct 7</div>
                      <div className="p50">Oct 21</div>
                      <div className="p90">Nov 12</div>
                    </div>
                  </div>
                </article>
              </header>

              <article className="p-portfolio-mix">
                <div className="kanban-board">
                  {cols.map(col => {
                    const apps = trackedApplications.filter(a => a.status === col);
                    return (
                      <div key={col} className="column" onDragOver={onDragOver} onDragLeave={onDragLeave} onDrop={(e) => onDrop(e, col)}>
                        <h3>{col} ({apps.length})</h3>
                        <div className="column-body">
                          {apps.length === 0 && <div style={{ border: '2px dashed var(--border)', borderRadius: 8, padding: 24, textAlign: 'center', color: 'var(--muted)', fontSize: 13 }}>Drag employers here</div>}
                          {apps.map(app => {
                            const emp = SEED_EMPLOYERS.find(e => e.id === app.employer_id) || SEED_EMPLOYERS[0];
                            return (
                              <div key={app.id} className="kanban-card" draggable onDragStart={(e) => onDragStart(e, app.id)}>
                                <h4>{emp.company_name}</h4>
                                <span className="role">{emp.role_title}</span>
                                <div className="progress-bar"><div className="fill" style={{ width: `${app.probability_score}%` }}></div></div>
                                <span className="next-action">Action: {app.next_action}</span>
                              </div>
                            );
                          })}
                        </div>
                      </div>
                    );
                  })}
                </div>
              </article>
            </motion.div>

            {showHitlModal && (
              <div className="modal-overlay" role="dialog" aria-modal="true">
                <article className="p-hitl" tabIndex="-1" ref={el => el && el.focus()} style={{ outline: 'none' }}>
                  <h3><lucide.AlertTriangle size={20} /> {MICRO_COPY['hitl.modal.title']}</h3>
                  <p>{MICRO_COPY['hitl.modal.body']}</p>
                  <div className="modal-actions">
                    <button className="btn-secondary" onClick={() => { setShowHitlModal(false); setPendingDrop(null); }}>{MICRO_COPY['hitl.button.cancel']}</button>
                    <button className="btn-primary" onClick={confirmDrop}>{MICRO_COPY['hitl.button.confirm']}</button>
                  </div>
                </article>
              </div>
            )}
          </section>
        );

      default: return null;
    }
  };

  return (
    <div style={{ position: 'relative' }}>
      <GlobalStyles />
      <main className={currentScreen === 'screen_05_tracking_board' ? 'nu-layout-full' : 'nu-layout-split'}>
        {renderSidebarChat()}
        {renderRightPane()}
      </main>

      {/* Toasts */}
      <div className="toast-container">
        <AnimatePresence>
          {toasts.map(t => (
            <motion.div key={t.id} className="toast" initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, scale: 0.9 }}>
              <lucide.CheckCircle2 size={16} color="var(--ok)" /> {t.msg}
            </motion.div>
          ))}
        </AnimatePresence>
      </div>

      {/* Demo Controls */}
      <div style={{ position: 'fixed', bottom: 16, right: 16, zIndex: 9999, background: 'var(--rail)', padding: '8px 12px', borderRadius: 8, display: 'flex', gap: 12, alignItems: 'center', boxShadow: 'var(--shadow-md)' }}>
        <span style={{ color: 'var(--muted)', fontSize: 11, textTransform: 'uppercase', fontWeight: 700 }}>Demo Jump</span>
        <select 
          value={currentScreen} 
          onChange={(e) => setCurrentScreen(e.target.value)} 
          style={{ color: 'var(--on-accent)', background: 'transparent', border: '1px solid var(--muted)', padding: '4px 8px', borderRadius: 4, fontSize: 13, outline: 'none' }}
        >
          <option value="screen_01_concierge_intro">01: Intro</option>
          <option value="screen_02_lookbook_curation">02: Lookbook</option>
          <option value="screen_03_employer_detail_gap">03: Detail</option>
          <option value="screen_04_gap_analysis_results">04: Gap Analysis</option>
          <option value="screen_05_tracking_board">05: Tracker</option>
        </select>
      </div>
    </div>
  );
};

function __test_state_transitions__() {
  console.assert(typeof App === 'function', 'App must be a component');
  return true;
}
if (typeof window !== 'undefined') {
  window.__hicProtoTests = __test_state_transitions__;
}
